text:
/* ─── Webflow design tokens ─────────────────────────────── */
body {
  font-family: Exo, var(--font-exo), sans-serif;
  font-size: 18px;
  line-height: 30px;
  font-weight: 400;
  color: var(--dark);
  background-color: var(--white);
}

h1, h2, h3, h4, h5, h6 { margin: 0; }
p { margin-top: 0; margin-bottom: 10px; }
ul { padding-left: 0; list-style: none; margin: 0; }
img { max-width: 100%; display: block; }

/* ─── Navbar ─────────────────────────────────────────────── */
.navbar {
  position: fixed;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  z-index: 9998;
  height: 88px;
  margin-top: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: width 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}


.navbar-shell {
  position: absolute;
  inset: 0;
  border-radius: 20px;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  pointer-events: none;
  transition: background-color 0.3s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.navbar-inner {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  width: 100%;
  padding: 0 max(2.5%, 16px);
  gap: 24px;
}

.navbar-logo {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  text-decoration: none;
  padding-left: 6px;
  pointer-events: auto;
  opacity: 1;
}

.navbar-links {
  display: flex;
  align-items: center;
  gap: 36px;
  flex: 1;
  justify-content: center;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-link {
  color: var(--secondary);
  letter-spacing: 0.03em;
  text-transform: uppercase;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  text-decoration: none;
  display: flex;
  align-items: center;
  position: relative;
  white-space: nowrap;
}

.nav-links {
  color: var(--secondary);
  font-weight: 600;
  font-size: 14px;
}

.link-line {
  background-color: var(--secondary);
  height: 1px;
  position: absolute;
  bottom: -3px;
  left: 0;
  width: 0;
  transition: width 0.25s ease;
}

.nav-link:hover .link-line { width: 100%; }

/* Hamburger — hidden on desktop */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  border: none;
  background: transparent;
  padding: 8px;
  margin-left: auto;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  z-index: 2;
}

.burger-line {
  display: block;
  width: 22px;
  height: 2px;
  border-radius: 2px;
  background-color: var(--dark);
  transition: transform 0.2s, opacity 0.2s;
}

.hamburger.is-open .burger-line:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.hamburger.is-open .burger-line:nth-child(2) {
  opacity: 0;
}
.hamburger.is-open .burger-line:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* Mobile menu overlay */
.mobile-menu {
  position: fixed;
  inset: 0;
  z-index: 99997;
  background-color: var(--white);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 32px;
  padding: 40px 24px;
}

.mobile-menu-close {
  position: absolute;
  top: 20px;
  left: 24px;
  right: auto;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background-color: var(--ticker);
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--dark);
  transition: background-color 0.2s;
}
/* .mobile-menu-close hover moved to @media (hover: hover) block below */

.mobile-nav-link {
  color: var(--secondary);
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  text-decoration: none;
  font-family: Exo, sans-serif;
}
@media (hover: hover) {
  .mobile-nav-link:hover { opacity: 0.7; }
  .mobile-menu-close:hover { background-color: var(--button-hover); }
}

/* ─── Hero ──────────────────────────────────────────────── */
.hero {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
  height: 100vh;
  min-height: 600px;
  position: relative;
  overflow: hidden;
  text-align: center;
}

.hero-background {
  z-index: 0;
  opacity: 0.55;
  background-image: url('/images/banner.png');
  background-position: 50%;
  background-repeat: no-repeat;
  background-size: cover;
  position: absolute;
  inset: 0;
}

.lottie-full-screen {
  z-index: 1;
  opacity: 0.5;
  mix-blend-mode: hard-light;
  width: 100%;
  height: 100%;
  display: block;
  position: absolute;
  overflow: hidden;
  pointer-events: none;
}

.hero-text {
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: 8px;
  position: relative;
  padding: 0 24px;
  max-width: 100%;
}

.line {
  z-index: 1;
  display: flex;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  position: relative;
}

.display-1 {
  letter-spacing: 0.03em;
  text-transform: capitalize;
  flex: none;
  margin: 0;
  font-size: clamp(2rem, 5.5vw, 3.8em);
  line-height: 1.15;
  font-family: Exo, sans-serif;
  font-weight: 700;
  color: var(--dark);
  white-space: nowrap;
}


/* Hero line fade-up entrance (baseline — always visible, animates in when CSS supports it) */
.hero-line {
  animation: heroFadeUp 0.7s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.hero-line:nth-child(1) { animation-delay: 0.1s; }
.hero-line:nth-child(2) { animation-delay: 0.2s; }
.hero-line:nth-child(3) { animation-delay: 0.3s; }

@keyframes heroFadeUp {
  0%   { opacity: 0; transform: translateY(40px); }
  100% { opacity: 1; transform: translateY(0); }
}

.text-serif {
  font-family: 'Playfair Display', var(--font-serif), serif;
}
.text-serif.cc-italic {
  letter-spacing: 0;
  text-transform: none;
  font-style: italic;
}
.text-serif.cc-underline {
  border-bottom: 3px solid var(--dark);
  display: inline-block;
  padding-bottom: 2px;
}

/* Bouncing balls */
.notsvg-blue,
.notsvg-purple {
  pointer-events: none;
  position: absolute;
}

.notsvg-blue {
  filter: invert(82%) sepia(35%) saturate(541%) hue-rotate(182deg) brightness(101%) contrast(93%);
}
.notsvg-purple {
  filter: invert(13%) sepia(21%) saturate(3474%) hue-rotate(277deg) brightness(91%) contrast(92%);
}

.notsvg-blue.bouncing-2.ball1  { top: 22%; left: 22%; width: 5vw; max-width: 96px; min-width: 44px; }
.notsvg-blue.bouncing.small-ball { bottom: 28%; left: 48%; width: 2vw; max-width: 36px; min-width: 18px; }
.notsvg-purple.bouncing-2      { top: 48%; left: 12%; width: 2.2vw; max-width: 38px; min-width: 18px; }
.notsvg-purple.bouncing.ball2  { top: 22%; right: 12%; width: 5vw; max-width: 96px; min-width: 44px; }
.notsvg-purple.bouncing.ball3  { bottom: 48%; left: 8%; width: 5vw; max-width: 96px; min-width: 44px; }
.notsvg-blue.bouncing-2.ball4  { bottom: 22%; right: 4%; width: 5vw; max-width: 96px; min-width: 44px; }

/* ─── Section structure ─────────────────────────────────── */
.section {
  margin-top: -120px;
  padding-top: 120px;
}

.section-homepage {
  margin-top: -120px;
  padding-top: 120px;
}

.container {
  width: 100%;
  max-width: 1290px;
  margin-left: auto;
  margin-right: auto;
  padding: 0 40px 60px;
  position: relative;
}

/* ─── Ticker ─────────────────────────────────────────────── */
.ticker-outer {
  overflow: hidden;
  width: 100%;
}

.ticker {
  background-color: var(--ticker);
  color: var(--dark);
  display: flex;
  flex-direction: row;
  padding: 28px 0 22px;
  overflow: hidden;
  width: 106%;
  position: relative;
}

.ticker-wrapper {
  backface-visibility: hidden;
  flex: none;
  display: flex;
  transform: perspective(1px);
}

.ticker-inner {
  display: flex;
  align-items: center;
  gap: 32px;
  padding-right: 32px;
  flex-shrink: 0;
}

.ticker-item {
  margin: 0;
  font-size: clamp(18px, 2.5vw, 26px);
  line-height: 1.2;
  font-weight: 700;
  font-family: Exo, sans-serif;
  white-space: nowrap;
}

/* ─── Works / projects ──────────────────────────────────── */
.projects-collection-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px 60px;
  padding-top: 80px;
}

.project:nth-child(odd) { margin-top: -80px; }

.image-link {
  display: block;
  position: relative;
  overflow: hidden;
  text-decoration: none;
  cursor: none;
}

.image-link.rounded {
  border-radius: var(--rounded);
  overflow: hidden;
}

.image-link .image {
  width: 100%;
  height: auto;
  display: block;
  transition: transform 0.5s cubic-bezier(0.25,0.46,0.45,0.94);
}

.image-link:hover .image {
  transform: scale(1.04);
}

/* "View More" overlay */
.view-more-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 0.25s ease;
  pointer-events: none;
}

.view-more-text {
  background-color: rgba(44,33,69,0.75);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  color: white;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  font-size: 14px;
  font-weight: 600;
  padding: 12px 20px;
  border-radius: 50px;
  font-family: Exo, sans-serif;
}

.image-link:hover .view-more-overlay { opacity: 1; }

/* ─── Skills ─────────────────────────────────────────────── */
.skills-grid {
  display: grid;
  grid-template-columns: 220px 1fr;
  gap: 60px;
  align-items: start;
  padding-top: 60px;
}

.skills-sticky {
  position: sticky;
  top: 120px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.skills-preview {
  width: 100%;
  aspect-ratio: 1;
  border-radius: var(--rounded);
  background-color: var(--ticker);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: opacity 0.3s;
}

.skill-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  border-bottom: 1px solid rgba(18,24,26,0.12);
  padding: 36px 0;
  cursor: default;
  align-items: start;
}

.skill-row:last-child { border-bottom: none; }

.skill-name-cell {
  display: flex;
  align-items: center;
  gap: 16px;
}

.skill-name {
  font-size: 17px;
  font-weight: 700;
  font-family: Exo, sans-serif;
  letter-spacing: 0.03em;
  color: var(--dark);
}

.skill-desc {
  margin: 0;
  font-size: 15px;
  line-height: 24px;
  color: var(--dark-70);
}

.skills-icons {
  filter: invert(13%) sepia(21%) saturate(3474%) hue-rotate(277deg) brightness(91%) contrast(92%);
  flex-shrink: 0;
}

/* ─── About ──────────────────────────────────────────────── */
.about-section {
  position: relative;
  overflow: hidden;
}

.display-3 {
  letter-spacing: 0.03em;
  text-transform: uppercase;
  font-size: clamp(28px, 3.5vw, 40px);
  line-height: 1.25;
  font-family: Exo, sans-serif;
  font-weight: 700;
}

.grid-2-columns {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  width: 100%;
  padding: 20px;
}

.rounded-img-about-section {
  border-radius: var(--rounded);
  width: 100%;
  height: auto;
}

.notsvg-pink-bg-big {
  position: absolute;
  left: -200px;
  top: -60px;
  width: 540px;
  height: auto;
  z-index: 0;
  pointer-events: none;
  filter: invert(93%) sepia(5%) saturate(382%) hue-rotate(323deg) brightness(103%) contrast(92%);
  opacity: 0.6;
}

/* ─── Contact ─────────────────────────────────────────────── */
.contact-section-inner {
  position: relative;
  z-index: 1;
}

.button-with-icon {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  border: 1.5px solid var(--secondary);
  border-radius: 50px;
  color: var(--secondary);
  letter-spacing: 0.03em;
  text-transform: uppercase;
  background-color: transparent;
  padding: 14px 14px 14px 22px;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 0.2s, color 0.2s;
  font-family: Exo, sans-serif;
}

.button-with-icon:hover {
  background-color: var(--secondary);
  color: var(--white);
}

.button-icon-wrapper {
  background-color: var(--secondary);
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 26px;
  height: 26px;
  flex-shrink: 0;
  transition: background-color 0.2s;
}

.button-with-icon:hover .button-icon-wrapper {
  background-color: rgba(255,255,255,0.25);
}

.button-icon { color: #fff; display: flex; align-items: center; }

/* ─── Popup ──────────────────────────────────────────────── */
.popup {
  position: fixed;
  inset: 0;
  z-index: 99999;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px;
  background-color: rgba(18,24,26,0.6);
  backdrop-filter: blur(4px);
}

.popup-wrap {
  background-color: var(--white);
  border-radius: 24px;
  width: 100%;
  max-width: 1000px;
  position: relative;
  max-height: 90vh;
  overflow: auto;
}

.popup-inner {
  padding: 60px;
}

.popup-close {
  background-color: var(--ticker);
  width: 34px;
  height: 34px;
  color: var(--dark);
  cursor: pointer;
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  position: absolute;
  top: 20px;
  right: 20px;
  border: none;
  transition: background-color 0.2s;
}
.popup-close:hover { background-color: var(--button-hover); }

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.sc-links {
  display: flex;
  gap: 10px;
  list-style: none;
  background-color: white;
  margin: 0;
  padding: 0;
}

.sc-link {
  background-color: var(--dark);
  width: 36px;
  height: 36px;
  color: var(--white);
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  text-decoration: none;
  transition: background-color 0.2s;
}
.sc-link:hover { background-color: var(--secondary); }

.text-field, .textarea {
  border: none;
  border-bottom: 1px solid var(--dark-70);
  background-color: transparent;
  color: var(--dark);
  font-size: 17px;
  line-height: 28px;
  font-family: Exo, sans-serif;
  padding: 8px 0 12px;
  width: 100%;
  outline: none;
  display: block;
}

.textarea { min-height: 100px; resize: vertical; }

.text-field::placeholder, .textarea::placeholder { color: var(--dark-70); }
.text-field:focus, .textarea:focus { border-bottom-color: var(--secondary); }

.submit-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background-color: var(--secondary);
  color: var(--white);
  letter-spacing: 0.03em;
  text-transform: uppercase;
  border-radius: 50px;
  padding: 13px 20px;
  font-size: 14px;
  font-weight: 600;
  border: none;
  cursor: pointer;
  font-family: Exo, sans-serif;
  transition: background-color 0.2s;
}
.submit-btn:hover { background-color: var(--dark); }

/* ─── Footer ─────────────────────────────────────────────── */
.footer {
  background-image: linear-gradient(180deg, rgba(18,24,26,0.7), rgba(18,24,26,0.9) 63%);
  color: var(--white);
}

.footer .sc-link {
  background-color: rgba(255, 255, 255, 0.15);
}
.footer .sc-link:hover {
  background-color: rgba(255, 255, 255, 0.35);
}

.footer .container {
  padding-top: 48px;
  padding-bottom: 40px;
}

.footer-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 20px;
  margin-bottom: 40px;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 20px;
  border-top: 1px solid rgba(255,255,255,0.12);
  padding-top: 28px;
}

.footer-nav-links {
  display: flex;
  gap: 28px;
  flex-wrap: wrap;
}

.footer-nav-link {
  color: rgba(255,255,255,0.65);
  font-size: 12px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  font-weight: 600;
  text-decoration: none;
  transition: color 0.2s;
}
.footer-nav-link:hover { color: #fff; }

.text-white { color: var(--white); }

/* ─── Inner page sections ───────────────────────────────── */
.page-sections {
  background-color: var(--white);
  color: var(--dark);
  padding-top: 160px;
  padding-bottom: 80px;
}

.project-body {
  display: flex;
  flex-direction: column;
  gap: 50px;
}

/* ─── Badges / misc ─────────────────────────────────────── */
.badge {
  background-color: var(--white);
  color: var(--dark);
  letter-spacing: 0.03em;
  text-transform: uppercase;
  border-radius: 50px;
  padding: 2px 12px;
  font-size: 13px;
  font-weight: 600;
  line-height: 23px;
  display: inline-block;
}

/* ─── Responsive ────────────────────────────────────────── */

/* Tablet landscape ≤ 1100px */
@media screen and (max-width: 1100px) {
  .navbar-links { gap: 20px; }
  .nav-links { font-size: 13px; }
  .projects-collection-list { gap: 40px; }
  .skills-grid { grid-template-columns: 200px 1fr; gap: 40px; }
  .container { padding: 0 24px 60px; }
}

/* Tablet portrait ≤ 991px — hamburger appears */
@media screen and (max-width: 991px) {
  .navbar { height: 76px; margin-top: 10px; }
  .navbar-links { display: none; }
  .hamburger { display: flex; }

  .display-1 { font-size: clamp(1.8rem, 6vw, 2.8rem); line-height: 1.2; white-space: normal; }

  .projects-collection-list {
    grid-template-columns: 1fr 1fr;
    gap: 32px;
    padding-top: 48px;
  }
  .project:nth-child(odd) { margin-top: 0; }

  .skills-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .skills-sticky { position: static; }
  .skills-preview { display: none; }
  .skill-row { grid-template-columns: 1fr; gap: 12px; }

  .grid-2-columns { grid-template-columns: 1fr; gap: 36px; }
  .notsvg-pink-bg-big { display: none; }

  .popup-inner { padding: 40px 32px; }
}

/* Mobile ≤ 767px */
@media screen and (max-width: 767px) {
  .navbar { height: 68px; margin-top: 8px; }

  .display-1 {
    font-size: clamp(1.5rem, 7.5vw, 2.2rem);
    line-height: 1.25;
    white-space: normal;
    word-break: break-word;
  }

  .line { gap: 6px; }

  .hero-text { padding: 0 16px; gap: 6px; }

  /* Smaller balls on mobile to avoid text overlap */
  .notsvg-blue.bouncing-2.ball1, .notsvg-purple.bouncing.ball2,
  .notsvg-purple.bouncing.ball3, .notsvg-blue.bouncing-2.ball4 {
    width: 3.5vw; max-width: 52px; min-width: 28px;
  }
  .notsvg-blue.bouncing.small-ball {
    width: 1.5vw; max-width: 24px; min-width: 12px;
  }
  .notsvg-purple.bouncing-2 {
    width: 1.8vw; max-width: 28px; min-width: 14px;
  }

  .ticker-item { font-size: 16px; }
  .ticker { padding: 20px 0 16px; }

  .projects-collection-list {
    grid-template-columns: 1fr;
    gap: 28px;
    padding-top: 40px;
  }

  .container { padding: 0 16px 40px; }

  .section-homepage { padding-top: 80px; margin-top: -80px; }
  .section { padding-top: 80px; margin-top: -80px; }

  .grid-2-columns { grid-template-columns: 1fr; gap: 28px; padding: 0; }

  .display-3 { font-size: clamp(22px, 6vw, 32px); }

  .section-2, .section-2-inner { padding: 60px 0 80px; }

  .popup-inner { padding: 28px 20px; }
  .popup-wrap { border-radius: 16px; }

  .footer-top { flex-direction: column; align-items: flex-start; }
  .footer-bottom { flex-direction: column; align-items: flex-start; gap: 16px; }

  .button-with-icon { font-size: 13px; padding: 12px 12px 12px 18px; }
}

/* Small mobile ≤ 480px */
@media screen and (max-width: 480px) {
  .display-1 {
    font-size: clamp(1.3rem, 8vw, 1.8rem);
  }
  .navbar-logo img { width: 52px !important; }
}

/* ─── Ball bounce animations ─────────────────────────────── */
@keyframes float1 {
  0%, 100% { transform: translate(0, 0) rotate(0deg); }
  25%       { transform: translate(8px, -14px) rotate(5deg); }
  50%       { transform: translate(-6px, -22px) rotate(-3deg); }
  75%       { transform: translate(-12px, -8px) rotate(2deg); }
}
@keyframes float2 {
  0%, 100% { transform: translate(0, 0) rotate(0deg); }
  33%       { transform: translate(-10px, -18px) rotate(-6deg); }
  66%       { transform: translate(12px, -10px) rotate(4deg); }
}
@keyframes float3 {
  0%, 100% { transform: translate(0, 0); }
  40%       { transform: translate(6px, -20px); }
  80%       { transform: translate(-8px, -12px); }
}
@keyframes float4 {
  0%, 100% { transform: translate(0, 0) scale(1); }
  50%       { transform: translate(-10px, -16px) scale(1.04); }
}

.notsvg-blue.bouncing-2.ball1  { animation: float1 6s ease-in-out infinite; }
.notsvg-blue.bouncing.small-ball { animation: float3 4.5s ease-in-out infinite; }
.notsvg-purple.bouncing-2      { animation: float2 5s ease-in-out infinite; animation-delay: 0.8s; }
.notsvg-purple.bouncing.ball2  { animation: float1 7s ease-in-out infinite; animation-delay: 1.2s; }
.notsvg-purple.bouncing.ball3  { animation: float3 5.5s ease-in-out infinite; animation-delay: 0.4s; }
.notsvg-blue.bouncing-2.ball4  { animation: float4 6.5s ease-in-out infinite; animation-delay: 1.8s; }

