}

.project-hero-image-inner {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.project-hero-image {
  object-fit: cover;
}

.project-hero-gradient {
  position: absolute;
  inset: 0;
  background: linear-gradient(
